const {test}=require('node:test'),assert=require('node:assert/strict'),F=require('../../reda-2/followup-summary.js');
const plan=(id='p1',version=1)=>({id,version,status:'active',activated_at:'2026-09-01T12:00:00Z',payload:{goal:'Fiktivt mål',schedule:{days:[1,3,5]},exercises:[{id:'chair',name:'Uppresning',variantLabel:'Med stöd',dose:{label:'2 × 8'}}]}});
const row=(date,status='completed',id='p1',version=1)=>({plan_id:id,plan_version:version,started_at:date+'T10:00:00Z',status,payload:{exercises:[{exerciseId:'chair',status:'completed',feedback:'okay'}]}});
const run=(sessions,plans=[plan()],extra={})=>F.build({plans,sessions,now:'2026-09-10T12:00:00Z',...extra});
test('scheduled days use unique completed days; partial and off-schedule are distinct',()=>{const f=run([row('2026-09-02'),row('2026-09-02'),row('2026-09-04','partial'),row('2026-09-05')]);assert.equal(f.scheduled,4);assert.equal(f.fulfilled,1);assert.equal(f.completed,3);assert.equal(f.trainingDays,2);assert.equal(f.partial,1);assert.equal(f.unplannedDays,1)});
test('historical plan owns names, goals, dose and issues even when exercise id is reused',()=>{const old=plan();old.status='superseded';const newer=plan('p2',2);newer.activated_at='2026-09-07T12:00:00Z';newer.payload.exercises[0].name='Belastad uppresning';const r=row('2026-09-04');r.payload.exercises[0].feedback='heavy';const f=run([r,row('2026-09-08','completed','p2',2)],[newer,old],{planId:'p1'});assert.equal(f.exercises[0].name,'Uppresning');assert.equal(f.exercises[0].heavy,1);assert.equal(f.completed,1);assert.equal(f.end,'2026-09-07')});
test('mismatching plan id never falls back to coincident version',()=>{assert.equal(run([row('2026-09-04','completed','another',1)]).completed,0)});
test('activation day and unfinished current day are excluded',()=>{const f=run([row('2026-09-01'),row('2026-09-10')]);assert.equal(f.completed,0);assert.equal(f.todaySessions,1);assert.equal(f.start,'2026-09-02')});
test('Stockholm day boundaries survive timezone and DST changes',()=>{assert.equal(F.day('2026-09-09T22:15:00Z'),'2026-09-10');assert.equal(F.shift('2026-03-29',1),'2026-03-30');assert.equal(F.shift('2026-10-25',1),'2026-10-26')});
test('truncated data is disclosed; complete coverage and missing schedule handled separately',()=>{assert.equal(run(Array.from({length:30},()=>row('2026-09-09'))).limited,true);const rows=Array.from({length:29},()=>row('2026-09-09'));rows.push(row('2026-08-01'));assert.equal(run(rows).limited,false);const p=plan();delete p.payload.schedule;assert.equal(run([],[p]).hasSchedule,false)});
test('no published plan and first day do not fabricate adherence',()=>{const p=plan();p.status='draft';assert.equal(run([],[p]),null);p.status='active';p.activated_at='2026-09-10T09:00:00Z';assert.equal(run([],[p]).emptyPeriod,true)});
